  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Maraviroc, a close analogue with a basic amine and lipophilic aromatic/fluorinated groups, has absolute oral bioavailability of 23–33% in humans across doses, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Odanacatib, which shares CF3 and amide/lactam-like polarity, showed absolute bioavailability of 30% at 50 mg fasted and 70% at 10 mg in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Aprepitant, containing CF3 groups and an ether/amide framework, has absolute bioavailability of 59–67% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Dutasteride, a lipophilic CF3-substituted amide, has absolute bioavailability approximately 60% (range 40–94%) in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Silodosin, with a trifluoroethoxy substituent and basic/amide features, has absolute bioavailability about 32% in healthy humans, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability ≥23%, mostly 30–70%, in humans. The physicochemical prior is mixed, but the consistent experimental evidence strongly supports F ≥20% for the query.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the exact query molecule.",
    "Exact solubility, permeability, and transporter behavior of the query are not experimentally characterized.",
    "The low neutral fraction at pH 7.4 could affect absorption, but this is not sufficient to overturn the consistent high-bioavailability evidence from close analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

